#!/usr/bin/env bash
# ======================================================
# OpenMT2 client - libFuzzer smoke run
# ======================================================
#
# Configures a clang + AddressSanitizer build with the TA.3 fuzz targets and
# runs each one for a bounded time. Random inputs are generated by libFuzzer;
# no game assets are used.
#
# Usage:
#   scripts/fuzz-smoke.sh                 # 10 s per target
#   scripts/fuzz-smoke.sh --seconds 60    # full 60 s run
#
# Environment:
#   FUZZ_SECONDS    seconds per target (default: 10)
#   FUZZ_BUILD      build directory (default: <root>/build-fuzz)
#   FUZZ_CORPUS     corpus directory (default: <root>/fuzz-corpus)
#   JOBS            parallel build jobs (default: nproc)
#   OPENMT2_IMAGE   container image for the host re-exec (default: openmt2/client)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(dirname "$SCRIPT_DIR")"

SECONDS_PER_TARGET="${FUZZ_SECONDS:-10}"
while [ "$#" -gt 0 ]; do
    case "$1" in
        --seconds|-s)
            SECONDS_PER_TARGET="${2:?--seconds needs a value}"
            shift 2
            ;;
        -h|--help)
            awk 'NR > 1 && /^#/ { sub(/^# ?/, ""); print; next } NR > 1 { exit }' "${BASH_SOURCE[0]}"
            exit 0
            ;;
        *)
            echo "unknown option: $1" >&2
            exit 2
            ;;
    esac
done

# Run inside the devkit image, where clang and the dependencies live.
if [ ! -f /.dockerenv ] && command -v docker >/dev/null 2>&1; then
    image="${OPENMT2_IMAGE:-openmt2/client}"
    mkdir -p "$ROOT/build-fuzz" "$ROOT/fuzz-corpus"
    exec docker run --rm --user "$(id -u):$(id -g)" -e HOME=/tmp \
        -e FUZZ_SECONDS="$SECONDS_PER_TARGET" \
        -v "$ROOT/src:/workspace/src" \
        -v "$ROOT/build-fuzz:/workspace/build-fuzz" \
        -v "$ROOT/fuzz-corpus:/workspace/fuzz-corpus" \
        -v "$ROOT/scripts:/workspace/scripts" \
        --entrypoint bash "$image" -c 'cd /workspace && ./scripts/fuzz-smoke.sh'
fi

BUILD="${FUZZ_BUILD:-$ROOT/build-fuzz}"
CORPUS="${FUZZ_CORPUS:-$ROOT/fuzz-corpus}"
JOBS="${JOBS:-$(nproc 2>/dev/null || echo 4)}"

if ! command -v clang++ >/dev/null 2>&1; then
    echo "[fuzz] clang++ not found; this script must run in the devkit image" >&2
    exit 1
fi

FLAGS="-fsanitize=fuzzer-no-link,address -fno-omit-frame-pointer -g -O1"

echo "[fuzz] configuring $BUILD (clang + ASan)"
cmake -S "$ROOT" -B "$BUILD" -G Ninja \
    -DCMAKE_BUILD_TYPE=RelWithDebInfo \
    -DBUILD_TESTS=ON \
    -DOPENMT2_BUILD_FUZZERS=ON \
    -DCMAKE_C_COMPILER=clang \
    -DCMAKE_CXX_COMPILER=clang++ \
    -DCMAKE_C_FLAGS="$FLAGS" \
    -DCMAKE_CXX_FLAGS="$FLAGS" >/dev/null

echo "[fuzz] building fuzz targets with $JOBS jobs"
cmake --build "$BUILD" --parallel "$JOBS" --target fuzz_gr2 fuzz_treecache fuzz_pack >/dev/null

mkdir -p "$CORPUS"
status=0
for name in gr2 treecache pack; do
    exe="$(find "$BUILD" -type f -name "fuzz_$name" -print -quit)"
    if [ -z "$exe" ]; then
        echo "[fuzz] missing target fuzz_$name" >&2
        status=1
        continue
    fi

    mkdir -p "$CORPUS/$name"
    echo "[fuzz] $name: ${SECONDS_PER_TARGET}s"
    if ! "$exe" -max_total_time="$SECONDS_PER_TARGET" -timeout=10 \
            -rss_limit_mb=2048 -max_len=1048576 -print_final_stats=1 \
            "$CORPUS/$name"; then
        echo "[fuzz] $name FAILED" >&2
        status=1
    fi
done

if [ "$status" -ne 0 ]; then
    echo "[fuzz] smoke run failed" >&2
    exit 1
fi

echo "[fuzz] all targets survived ${SECONDS_PER_TARGET}s"
